-- 3.6: squad bingo. A card a week, the same for every squad: the server
-- draws it once from the pool (bingo_pool, the admin edits it) and keeps it
-- (bingo_cards), so every board plays the same card and an edit shows from
-- the next week's draw. Each member's row carries `play`: facts about their
-- own week (which squares they passed, the days they studied, cheers sent),
-- the same in every squad they're in; boards add the rows up.
ALTER TABLE members ADD COLUMN play TEXT;
CREATE TABLE bingo_pool (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,            -- square | middle
  json TEXT NOT NULL,            -- the entry: its words, rule type and numbers
  enabled INTEGER NOT NULL DEFAULT 1,
  updated_at INTEGER NOT NULL
);
CREATE TABLE bingo_cards (
  wk TEXT PRIMARY KEY,           -- 2026-W40
  json TEXT NOT NULL,            -- the card as drawn: 8 squares and the middle
  stats TEXT,                    -- the daily cron's counts: how many stamped each square
  created_at INTEGER NOT NULL
);
